function currentPageContent(key) { return {...editablePageDefaults[key], ...(siteContent.pages?.[key] || {})}; }

function pageEditorFields() {
  return Object.entries(editablePageDefaults).map(([key, defaults]) => {
    const page=currentPageContent(key);
    const blocks=page.blocks||[];
    const questions=page.questions||[];
    const labels={nosotros:'Nosotros',contacto:'Contacto',envios:'Envíos y entregas',cambios:'Cambios y devoluciones',faq:'Preguntas frecuentes',terminos:'Términos y condiciones',privacidad:'Política de privacidad',cookies:'Política de cookies'};
    return `<fieldset class="page-editor-card"><legend>${labels[key]}</legend><div class="form-grid"><label>Título<input name="pages.${key}.title" required value="${page.title||''}"></label><label>Imagen (URL)<input name="pages.${key}.image" value="${page.image||''}"></label><label class="full-field">Subir imagen<input name="pages.${key}.imageFile" type="file" accept="image/*"></label><label class="full-field">Texto introductorio<textarea name="pages.${key}.intro" required>${page.intro||''}</textarea></label>${blocks.map((block,i)=>`<label>Bloque ${i+1} — título<input name="pages.${key}.block${i}Title" value="${block[0]||''}"></label><label>Bloque ${i+1} — texto<input name="pages.${key}.block${i}Text" value="${block[1]||''}"></label>`).join('')}${questions.map((item,i)=>`<label class="full-field">Pregunta ${i+1}<input name="pages.${key}.question${i}" value="${item[0]||''}"></label><label class="full-field">Respuesta ${i+1}<textarea name="pages.${key}.answer${i}">${item[1]||''}</textarea></label>`).join('')}${key==='contacto'?`<label>Encabezado del formulario<input name="pages.contacto.contactHeading" value="${page.contactHeading||''}"></label><label>Texto del formulario<input name="pages.contacto.contactText" value="${page.contactText||''}"></label><label>Encabezado lateral<input name="pages.contacto.asideHeading" value="${page.asideHeading||''}"></label><label>Texto lateral<input name="pages.contacto.asideText" value="${page.asideText||''}"></label>`:''}</div></fieldset>`;
  }).join('');
}

function categoryEditorFields() {
  return `<div class="category-editors"><h3>Imágenes de categorías</h3><p>Actualiza las fotos que aparecen en la portada. Puedes pegar una URL o subir una imagen.</p><div class="category-image-grid">${categories.map((category,index)=>`<div class="category-image-field"><strong>${category.name}</strong><img src="${category.image}" alt="${category.name}"><input name="categoryImage${index}" value="${category.image}" placeholder="URL de imagen"><input name="categoryImageFile${index}" type="file" accept="image/*"></div>`).join('')}</div></div>`;
}

async function buildEditablePages(form) {
  const pages={};
  for (const [key, defaults] of Object.entries(editablePageDefaults)) {
    const page={...currentPageContent(key), title:form.get(`pages.${key}.title`), intro:form.get(`pages.${key}.intro`), image:form.get(`pages.${key}.image`)};
    const imageFile=document.querySelector(`[name="pages.${key}.imageFile"]`)?.files?.[0];
    if (imageFile) page.image=await uploadProductImage(imageFile);
    if (defaults.blocks) page.blocks=defaults.blocks.map((_,i)=>[form.get(`pages.${key}.block${i}Title`),form.get(`pages.${key}.block${i}Text`)]);
    if (defaults.questions) page.questions=defaults.questions.map((_,i)=>[form.get(`pages.${key}.question${i}`),form.get(`pages.${key}.answer${i}`)]);
    if (key==='contacto') Object.assign(page,{contactHeading:form.get('pages.contacto.contactHeading'),contactText:form.get('pages.contacto.contactText'),asideHeading:form.get('pages.contacto.asideHeading'),asideText:form.get('pages.contacto.asideText')});
    pages[key]=page;
  }
  return pages;
}

