async function loadProducts() {
  if (!supabase) return;
  const { data, error } = await supabase.from('products').select('*').eq('active', true).order('created_at', { ascending: false });
  if (error) { state.dbError = error.message; return; }
  products = (data || []).map(mapProduct);
}

async function loadContent() {
  if (!supabase) return;
  const { data, error } = await supabase.from('site_content').select('content').eq('id', 1).maybeSingle();
  if (error) { state.dbError = error.message; return; }
  if (data?.content) siteContent = {...defaultContent, ...data.content};
  if (siteContent.categoryImages) categories = categories.map((category) => ({...category, image: siteContent.categoryImages[category.name] || category.image}));
  heroImages[0] = siteContent.heroImage || defaultContent.heroImage;
}

async function refreshSession() {
  if (!supabase) return;
  const { data } = await supabase.auth.getSession();
  state.user = data.session?.user || null;
  state.profile = null;
  state.isAdmin = false;
  if (state.user) {
    const profile = await supabase.from('profiles').select('role,full_name').eq('id', state.user.id).maybeSingle();
    state.profile = profile.data || null;
    state.isAdmin = profile.data?.role === 'admin';
  }
}

async function loadAdminData() {
  if (!supabase || !state.isAdmin) return;
  state.adminBusy = true;
  const [productResult, orderResult, messageResult, subscriberResult] = await Promise.all([
    supabase.from('products').select('*').order('created_at', { ascending: false }),
    supabase.from('orders').select('*, order_items(*)').order('created_at', { ascending: false }),
    supabase.from('contact_messages').select('*').order('created_at', { ascending: false }),
    supabase.from('newsletter_subscribers').select('*').order('created_at', { ascending: false })
  ]);
  state.adminProducts = (productResult.data || []).map(mapProduct);
  state.adminOrders = orderResult.data || [];
  state.adminMessages = messageResult.data || [];
  state.adminSubscribers = subscriberResult.data || [];
  state.adminMessagesError = messageResult.error?.message || '';
  state.adminSubscribersError = subscriberResult.error?.message || '';
  state.adminBusy = false;
  const firstError = productResult.error || orderResult.error || messageResult.error || subscriberResult.error;
  if (firstError) state.dbError = firstError.message;
}

const orderNumber = () => `LV-${new Date().getFullYear()}-${String(Math.floor(Math.random() * 1000000)).padStart(6, '0')}`;

async function saveOrder(form) {
  const number = orderNumber();
  if (!supabase) return number;
  const shipping = cartTotal() >= 180000 ? 0 : 9900;
  const payload = {
    id: crypto.randomUUID(),
    order_number: number,
    customer_name: form.get('name'),
    email: form.get('email'),
    phone: form.get('phone'),
    address: form.get('address'),
    city: form.get('city'),
    payment_method: 'contraentrega',
    shipping_carrier: 'Interrapidísimo',
    subtotal: cartTotal(),
    shipping,
    total: cartTotal() + shipping,
    status: 'new'
  };
  const { error } = await supabase.from('orders').insert(payload);
  if (error) throw error;
  const items = state.cart.map(item => ({ order_id: payload.id, product_id: item.id, product_name: item.name, price: item.price, quantity: item.qty, color: item.color, size: item.size, image: item.image }));
  const itemResult = await supabase.from('order_items').insert(items);
  if (itemResult.error) throw itemResult.error;
  return payload.order_number;
}

