function addToCart(id, qty=1, options={}) { const p=products.find(item=>item.id===id); if(!p)return; const key=id+'-'+(options.color||p.colors[0])+'-'+(options.size||p.sizes[0]); const found=state.cart.find(item=>item.key===key); if(found)found.qty+=qty; else state.cart.push({key,id,name:p.name,price:p.price,image:p.image,qty,color:options.color||p.colors[0],size:options.size||p.sizes[0]}); saveState(); state.cartOpen=true; state.detail=null; render(); toast(`${p.name} se añadió a tu carrito`); }
function bindEvents() {
  document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click', e=>{ const target=e.currentTarget, action=target.dataset.action; if((action==='close-detail'||action==='close-cart') && (target.classList.contains('modal-backdrop')||target.classList.contains('drawer-backdrop')) && e.target.closest('[data-stop="true"]'))return;
    if(action==='accept-cookies'||action==='reject-cookies'){localStorage.setItem('luvia-cookie-consent',action==='accept-cookies'?'accepted':'rejected');render();}
    if(action==='open-cart'){state.cartOpen=true;render();}
    if(action==='close-cart'){state.cartOpen=false;render();}
    if(action==='mobile-nav'){document.querySelector('.main-nav')?.classList.toggle('is-open');}
    if(action==='detail'){state.detail=target.dataset.id;render();}
    if(action==='close-detail'){state.detail=null;render();}
    if(action==='thumb'){document.querySelector('#detail-main-image').src=target.dataset.image; document.querySelectorAll('.thumb').forEach(t=>t.classList.remove('active'));target.classList.add('active');}
    if(action==='favorite'){const id=target.dataset.id; state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];saveState();render();toast(state.favorites.includes(id)?'Guardado en tus favoritos':'Quitado de tus favoritos');}
    if(action==='quick-add'){addToCart(target.dataset.id);}
    if(action==='detail-add'){const color=document.querySelector('.swatch.active')?.dataset.color, size=document.querySelector('.size-option.active')?.dataset.size, qty=Number(document.querySelector('#detail-qty')?.textContent||1);addToCart(target.dataset.id,qty,{color,size});}
    if(action==='detail-qty'){const el=document.querySelector('#detail-qty');el.textContent=Math.max(1,Number(el.textContent)+Number(target.dataset.change));}
    if(action==='color'){document.querySelectorAll('.swatch').forEach(s=>{s.classList.remove('active');s.setAttribute('aria-pressed','false')});target.classList.add('active');target.setAttribute('aria-pressed','true');document.querySelector('#selected-color').textContent=target.dataset.color;}
    if(action==='size'){document.querySelectorAll('.size-option').forEach(s=>{s.classList.remove('active');s.setAttribute('aria-pressed','false')});target.classList.add('active');target.setAttribute('aria-pressed','true');}
    if(action==='cart-qty'){const item=state.cart.find(i=>i.key===target.dataset.key);if(item){item.qty=Math.max(1,item.qty+Number(target.dataset.change));saveState();render();}}
    if(action==='remove-cart'){state.cart=state.cart.filter(i=>i.key!==target.dataset.key);saveState();render();toast('Producto eliminado del carrito');}
    if(action==='checkout'){if(!state.cart.length){toast('Agrega productos antes de continuar');return;}state.cartOpen=false;state.checkout=true;render();}
    if(action==='close-checkout'){state.checkout=false;if(location.pathname==='/checkout')location.hash='inicio';render();}
    if(action==='finish-order'){state.checkout=false;state.cart=[];saveState();if(location.pathname==='/checkout')location.hash='inicio';render();}
    if(action==='hero-prev'){state.heroSlide=(state.heroSlide+heroImages.length-1)%heroImages.length;render();}
    if(action==='hero-next'){state.heroSlide=(state.heroSlide+1)%heroImages.length;render();}
    if(action==='browse-all'){location.hash='tienda';state.category='Todos';render();window.scrollTo({top:0,behavior:'smooth'});}
    if(action==='category'||action==='filter'){state.category=target.dataset.category;location.hash='tienda';render();window.scrollTo({top:0,behavior:'smooth'});}
    if(action==='clear-search'){state.search='';render();}
    if(action==='scroll-store'){location.hash='tienda';render();window.scrollTo({top:0,behavior:'smooth'});}
    if(action==='account'){location.hash='cuenta';render();window.scrollTo({top:0,behavior:'smooth'});}
    if(action==='favorites'){toast(state.favorites.length?`Tienes ${state.favorites.length} favoritos guardados`:'Aún no tienes favoritos');}
    if(action==='admin-tab'){state.adminTab=target.dataset.tab;render();}
    if(action==='order-filter'){state.orderFilter=target.dataset.filter;render();}
    if(action==='message-filter'){state.messageFilter=target.dataset.filter;render();}
    if(action==='signout'){supabase?.auth.signOut();state.user=null;state.profile=null;state.isAdmin=false;render();}
    if(action==='edit-product'){state.editingProduct=state.adminProducts.find(item=>item.id===target.dataset.id)||null;render();window.scrollTo({top:0,behavior:'smooth'});}
    if(action==='cancel-product-edit'){state.editingProduct=null;render();}
    if(action==='delete-product'){if(!supabase||!state.isAdmin)return;if(window.confirm('¿Eliminar este producto del catálogo?')){supabase.from('products').delete().eq('id',target.dataset.id).then(async({error})=>{if(error)toast(error.message);else{toast('Producto eliminado');state.editingProduct=null;await loadAdminData();await loadProducts();render();}});}}
    if(action==='refresh-admin'){loadAdminData().then(()=>render());}
    if(action==='about'){location.hash='nosotros';render();window.scrollTo({top:0,behavior:'smooth'});}
  }));
  document.querySelector('#global-search-form')?.addEventListener('submit', e=>{e.preventDefault();const input=e.currentTarget.querySelector('#global-search');state.searchDraft=input?.value.trim()||'';state.search=state.searchDraft;state.category='Todos';if(location.hash!=='#tienda')location.hash='tienda';else{render();const nextInput=document.querySelector('#global-search');nextInput?.focus();nextInput?.setSelectionRange(nextInput.value.length,nextInput.value.length);}});
  document.querySelector('#global-search')?.addEventListener('input', e=>{state.searchDraft=e.target.value;document.querySelector('#global-search-form')?.classList.toggle('has-value',Boolean(state.searchDraft.trim()));});
  document.querySelector('#sort-products')?.addEventListener('change', e=>{state.sort=e.target.value;render();});
  document.querySelector('#account-login-form')?.addEventListener('submit', async e=>{e.preventDefault();const form=new FormData(e.currentTarget);const {error}=await supabase.auth.signInWithPassword({email:form.get('email'),password:form.get('password')});if(error){toast('No pudimos iniciar sesión: '+error.message);return;}await refreshSession();render();toast('Bienvenida/o a tu cuenta Luvia.');});
  document.querySelector('#account-signup-form')?.addEventListener('submit', async e=>{e.preventDefault();const form=new FormData(e.currentTarget);const {data,error}=await supabase.auth.signUp({email:form.get('email'),password:form.get('password'),options:{data:{full_name:form.get('name')}}});if(error){toast('No pudimos crear tu cuenta: '+error.message);return;}if(data.session){await refreshSession();render();toast('Tu cuenta Luvia fue creada.');}else{toast('Cuenta creada. Revisa tu correo para confirmar el registro.');}});
  document.querySelector('#admin-login-form')?.addEventListener('submit', async e=>{e.preventDefault();const form=new FormData(e.currentTarget);const {error}=await supabase.auth.signInWithPassword({email:form.get('email'),password:form.get('password')});if(error){toast(error.message);return;}await refreshSession();await loadAdminData();render();});
  document.querySelector('#content-form')?.addEventListener('submit', async e=>{e.preventDefault();if(!supabase||!state.isAdmin)return;const formElement=e.currentTarget;const form=new FormData(formElement);try{const heroFile=document.querySelector('[name="heroImageFile"]')?.files?.[0];const editorialFile=document.querySelector('[name="editorialImageFile"]')?.files?.[0];const aboutFile=document.querySelector('[name="aboutImageFile"]')?.files?.[0];const [heroUrl,editorialUrl,aboutUrl]=await Promise.all([uploadProductImage(heroFile),uploadProductImage(editorialFile),uploadProductImage(aboutFile)]);const categoryImages={};for(let index=0;index<categories.length;index++){const file=document.querySelector(`[name="categoryImageFile${index}"]`)?.files?.[0];const uploaded=await uploadProductImage(file);categoryImages[categories[index].name]=uploaded||form.get(`categoryImage${index}`);};const nextContent={heroTitle:form.get('heroTitle'),heroTitleEm:form.get('heroTitleEm'),heroSubtitle:form.get('heroSubtitle'),heroImage:heroUrl||form.get('heroImage'),editorialEyebrow:form.get('editorialEyebrow'),editorialTitle:form.get('editorialTitle'),editorialTitleEm:form.get('editorialTitleEm'),editorialText:form.get('editorialText'),editorialImage:editorialUrl||form.get('editorialImage'),aboutTitle:form.get('aboutTitle'),aboutText:form.get('aboutText'),aboutImage:aboutUrl||form.get('aboutImage'),socialInstagram:form.get('socialInstagram'),socialFacebook:form.get('socialFacebook'),socialTikTok:form.get('socialTikTok'),socialYoutube:form.get('socialYoutube'),pages:await buildEditablePages(form),categoryImages};const {error}=await supabase.from('site_content').upsert({id:1,content:nextContent,updated_at:new Date().toISOString()});if(error)throw error;siteContent={...defaultContent,...nextContent};categories=categories.map((category)=>({...category,image:siteContent.categoryImages?.[category.name]||category.image}));heroImages[0]=siteContent.heroImage;toast('Contenido actualizado');render();}catch(error){toast('No se pudo guardar el contenido: '+error.message);}});
  document.querySelector('#product-form')?.addEventListener('submit', async e=>{e.preventDefault();if(!supabase||!state.isAdmin)return;const formElement=e.currentTarget;const form=new FormData(formElement);const file=document.querySelector('#product-image-file')?.files?.[0];try{state.adminBusy=true;const image=await uploadProductImage(file);const payload=mapProductPayload({name:form.get('name'),slug:form.get('slug'),category:form.get('category'),price:form.get('price'),old_price:form.get('old_price'),stock:form.get('stock'),tag:form.get('tag'),image:form.get('image'),colors:form.get('colors'),sizes:form.get('sizes'),description:form.get('description')},image);const id=formElement.dataset.id;const result=id?await supabase.from('products').update(payload).eq('id',id):await supabase.from('products').insert(payload);if(result.error)throw result.error;toast(id?'Producto actualizado':'Producto agregado');state.editingProduct=null;await loadAdminData();await loadProducts();render();}catch(error){toast('No se pudo guardar: '+error.message);}finally{state.adminBusy=false;}});
  document.querySelectorAll('[data-action="update-status"]').forEach(select=>select.addEventListener('change',async e=>{const selectElement=e.currentTarget;const order=state.adminOrders.find(item=>item.id===selectElement.dataset.id);const previous=order?.status||'new';selectElement.disabled=true;const {error}=await supabase.from('orders').update({status:selectElement.value}).eq('id',selectElement.dataset.id);selectElement.disabled=false;if(error){selectElement.value=previous;toast('No se pudo actualizar el pedido: '+error.message);}else{if(order)order.status=selectElement.value;toast('Estado del pedido actualizado');}}));
  document.querySelectorAll('[data-action="update-message-status"]').forEach(select=>select.addEventListener('change',async e=>{const selectElement=e.currentTarget;const message=state.adminMessages.find(item=>item.id===selectElement.dataset.id);const previous=message?.status||'new';selectElement.disabled=true;const {error}=await supabase.from('contact_messages').update({status:selectElement.value}).eq('id',selectElement.dataset.id);selectElement.disabled=false;if(error){selectElement.value=previous;toast('No se pudo actualizar el mensaje: '+error.message);}else{if(message)message.status=selectElement.value;toast('Estado del mensaje actualizado');}}));
  document.querySelector('#contact-form')?.addEventListener('submit', async e=>{e.preventDefault();const formElement=e.currentTarget;if(!supabase){toast('Conecta Supabase para enviar el mensaje');return;}const form=new FormData(formElement);try{const {error}=await supabase.from('contact_messages').insert({name:form.get('name'),email:form.get('email'),subject:form.get('subject'),message:form.get('message')});if(error)throw error;formElement.reset();toast('Mensaje recibido. Te responderemos pronto.');}catch(error){toast('No pudimos enviar tu mensaje: '+error.message);}});
  document.querySelector('#newsletter-form')?.addEventListener('submit', async e=>{e.preventDefault();const formElement=e.currentTarget;if(!supabase){toast('Conecta Supabase para suscribirte');return;}const form=new FormData(formElement);try{const {error}=await supabase.from('newsletter_subscribers').insert({email:String(form.get('email')).trim().toLowerCase(),source:'footer'});if(error){if(error.code==='23505'){formElement.reset();toast('Este correo ya está suscrito a Luvia.');return;}throw error;}formElement.reset();toast('¡Listo! Te enviaremos novedades de Luvia.');}catch(error){toast('No pudimos registrar tu correo: '+error.message);}});
  document.querySelector('#checkout-form')?.addEventListener('submit', async e=>{e.preventDefault();const form=new FormData(e.currentTarget);if(!form.get('name')||!form.get('email')||!form.get('address')||!form.get('city')||!form.get('phone'))return;try{const number=await saveOrder(form);document.querySelector('.checkout-modal')?.parentElement?.remove();app.insertAdjacentHTML('beforeend',confirmationModal(number));document.querySelector('[data-action="finish-order"]')?.addEventListener('click',()=>{state.checkout=false;state.cart=[];saveState();render();});}catch(error){toast('No pudimos registrar el pedido: '+error.message);}});
}
window.addEventListener('hashchange',()=>{ if(!state.checkout){state.detail=null;render();window.scrollTo({top:0,behavior:'smooth'});}});
render();
if (supabase) {
  supabase.auth.onAuthStateChange(async (_event, session) => { state.user=session?.user||null; await refreshSession(); if(location.hash==='#admin') { await loadAdminData(); render(); } });
  Promise.all([loadProducts(), loadContent(), refreshSession()]).then(async()=>{ if(location.hash==='#admin') await loadAdminData(); render(); });
}
